fn decode_cyclic(s: &Vec<i8>) -> Vec<i8> {
    let L = s.len();
    let P = L - (L % 3);
    let mut res = Vec::with_capacity(L);

    for i in 0..L {
        if i < P {
            match i % 3 {
                0 => res.push(s[i + 2]),
                1 => res.push(s[i - 1]),
                2 => res.push(s[i]), // For i mod 3 == 2, it is not explicitly stated to change, so just copy input
                _ => unreachable!(),
            }
        } else {
            // For the suffix (i in [P, L)), output equals input
            res.push(s[i]);
        }
    }

    res
}